-- AGGREGATION POLICY comprehensive test fixture
-- Tests CREATE, ALTER, DROP with various options
-- CREATE AGGREGATION POLICY - simple
CREATE AGGREGATION POLICY simple_policy AS () RETURNS AGGREGATION_CONSTRAINT -> NO_AGGREGATION_CONSTRAINT;
-- CREATE AGGREGATION POLICY - with MIN_GROUP_SIZE
CREATE AGGREGATION POLICY sized_policy AS () RETURNS AGGREGATION_CONSTRAINT -> AGGREGATION_CONSTRAINT(MIN_GROUP_SIZE => 5);
-- CREATE OR REPLACE
CREATE OR REPLACE AGGREGATION POLICY replaced_policy AS () RETURNS AGGREGATION_CONSTRAINT -> AGGREGATION_CONSTRAINT(MIN_GROUP_SIZE => 10);
-- CREATE IF NOT EXISTS
CREATE AGGREGATION POLICY IF NOT EXISTS conditional_policy AS () RETURNS AGGREGATION_CONSTRAINT -> NO_AGGREGATION_CONSTRAINT;
-- CREATE with COMMENT
CREATE AGGREGATION POLICY documented_policy AS () RETURNS AGGREGATION_CONSTRAINT -> NO_AGGREGATION_CONSTRAINT COMMENT = 'Policy for data aggregation';
-- CREATE with qualified name
CREATE AGGREGATION POLICY db.schema.qualified_policy AS () RETURNS AGGREGATION_CONSTRAINT -> AGGREGATION_CONSTRAINT(MIN_GROUP_SIZE => 3);
-- CREATE with CASE expression body
CREATE AGGREGATION POLICY conditional_agg AS () RETURNS AGGREGATION_CONSTRAINT ->
  CASE
    WHEN CURRENT_ROLE() IN ('ANALYST', 'DATA_SCIENTIST') THEN AGGREGATION_CONSTRAINT(MIN_GROUP_SIZE => 5)
    ELSE NO_AGGREGATION_CONSTRAINT
  END;
-- ALTER AGGREGATION POLICY - RENAME TO
ALTER AGGREGATION POLICY old_policy RENAME TO new_policy;
-- ALTER AGGREGATION POLICY - SET BODY
ALTER AGGREGATION POLICY my_policy SET BODY -> AGGREGATION_CONSTRAINT(MIN_GROUP_SIZE => 7);
-- ALTER AGGREGATION POLICY - IF EXISTS SET BODY
ALTER AGGREGATION POLICY IF EXISTS my_policy SET BODY -> NO_AGGREGATION_CONSTRAINT;
-- ALTER AGGREGATION POLICY - SET TAG
ALTER AGGREGATION POLICY my_policy SET TAG governance_tag = 'pii';
-- ALTER AGGREGATION POLICY - UNSET TAG
ALTER AGGREGATION POLICY my_policy UNSET TAG governance_tag;
-- ALTER AGGREGATION POLICY - SET COMMENT
ALTER AGGREGATION POLICY my_policy SET COMMENT = 'Updated policy comment';
-- ALTER AGGREGATION POLICY - UNSET COMMENT
ALTER AGGREGATION POLICY my_policy UNSET COMMENT;
-- DROP AGGREGATION POLICY - simple
DROP AGGREGATION POLICY my_policy;
-- DROP AGGREGATION POLICY - IF EXISTS
DROP AGGREGATION POLICY IF;
EXISTS old_policy;
-- DROP AGGREGATION POLICY - qualified name
DROP AGGREGATION POLICY IF;
EXISTS db.schema.qualified_policy;